import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.BWTY_seE.js";const m=JSON.parse('{"title":"AI 动态 · 2026-11-01","description":"","frontmatter":{"title":"AI 动态 · 2026-11-01","date":"2026-11-01T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-11/ai-news-2026-11-01.md","filePath":"news/2026-11/ai-news-2026-11-01.md","lastUpdated":null}'),n={name:"news/2026-11/ai-news-2026-11-01.md"};function i(o,e,l,c,p,d){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-11-01" tabindex="-1">AI 动态 · 2026-11-01 <a class="header-anchor" href="#ai-动态-·-2026-11-01" aria-label="Permalink to &quot;AI 动态 · 2026-11-01&quot;">​</a></h1><blockquote><p>截至 2026-11-01。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="openai-新一轮融资目标据报下调" tabindex="-1">OpenAI 新一轮融资目标据报下调 <a class="header-anchor" href="#openai-新一轮融资目标据报下调" aria-label="Permalink to &quot;OpenAI 新一轮融资目标据报下调&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-01">2026-11-01</time></p><p>TechCrunch 报道，OpenAI 最新一轮融资未能达到预期，公司已下调募资目标。这一信号出现在 AI 基建投入持续膨胀、资本市场对高估值容忍度收紧的背景下，头部实验室的融资节奏与定价逻辑可能随之调整。对读者：关注后续估值与算力采购承诺是否同步收缩，评估依赖 OpenAI 生态的产品在价格与配额上的潜在波动。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/31/openai-reportedly-lowers-funding-target-for-new-round/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="naacp-诉-xai-数据中心污染案获准继续审理" tabindex="-1">NAACP 诉 xAI 数据中心污染案获准继续审理 <a class="header-anchor" href="#naacp-诉-xai-数据中心污染案获准继续审理" aria-label="Permalink to &quot;NAACP 诉 xAI 数据中心污染案获准继续审理&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-01">2026-11-01</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/fe25dd04ea85.jpg" alt="配图"></p><p>法官裁定 NAACP 针对 xAI 数据中心违反《清洁空气法》的诉讼可以继续推进。该案把 AI 算力扩张的环境外部性推上法庭，若最终形成判例，可能影响数据中心选址、环评流程与运营成本。对读者：在规划大规模推理/训练集群时，提前把环保合规与社区沟通纳入项目风险清单。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/31/judge-allows-naacp-lawsuit-over-xai-data-center-pollution-to-move-forward/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="我用-50-美元自制了一个-ai「拓麻歌子」" tabindex="-1">我用 50 美元自制了一个 AI「拓麻歌子」 <a class="header-anchor" href="#我用-50-美元自制了一个-ai「拓麻歌子」" aria-label="Permalink to &quot;我用 50 美元自制了一个 AI「拓麻歌子」&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-01">2026-11-01</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/344828d6a25e.jpg" alt="配图"></p><p>The Verge 作者用 Waveshare ESP32-S3 开发板复刻 Meta 即将发售的 Muse Charm：没有摄像头和 5G，但能真正与 Muse 对话、显示可爱头像，还兼作怀表与远程取景器。Meta 一边准备出货，一边也在帮用户用现成硬件写类似小玩意。对读者：硬件类 AI 玩具的差异化正快速被开源硬件抹平，选型时可先评估可 DIY 替代性。</p><p class="news-entry-source"><a href="https://www.theverge.com/gadgets/1013375/muse-charm-gadgets-preview-waveshare-esp32-claude-vibe-code" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="zest-推出短信-ai-代理-帮你找餐厅并订位" tabindex="-1">Zest 推出短信 AI 代理，帮你找餐厅并订位 <a class="header-anchor" href="#zest-推出短信-ai-代理-帮你找餐厅并订位" aria-label="Permalink to &quot;Zest 推出短信 AI 代理，帮你找餐厅并订位&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-10-31">2026-10-31</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/e194a0f19cbf.webp" alt="配图"></p><p>Zest 的新 AI 代理通过短信交互解决「吃什么」的争执：汇总每个人的口味偏好、把候选餐厅交给群里投票，最后直接完成预订。这类轻量 concierge 产品把 Agent 能力嵌进最普适的消息入口，绕开了 App 安装门槛。对读者：关注其预订链路是否直连餐厅系统，这决定了体验上限与可复制性。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/30/zests-new-ai-agent-finds-restaurants-and-books-reservations-over-text/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="nace-ai-开源-drex-max-v1-27b-决策模型可在-apple-silicon-本地运行" tabindex="-1">Nace AI 开源 Drex Max v1：27B 决策模型可在 Apple Silicon 本地运行 <a class="header-anchor" href="#nace-ai-开源-drex-max-v1-27b-决策模型可在-apple-silicon-本地运行" aria-label="Permalink to &quot;Nace AI 开源 Drex Max v1：27B 决策模型可在 Apple Silicon 本地运行&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-01">2026-11-01</time></p><p>Nace AI 开源 Drex Max v1，这是一个 27B 多模态决策模型，评测得分 67.52，可在 Apple Silicon 上本地运行。中等参数规模加本地推理的组合，意味着隐私敏感或离线场景有了新的可选方案。对读者：可在 Mac 上先跑通评测基线，再判断是否值得替换现有云端推理链路。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/01/nace-ai-open-sources-drex-max-v1-local-inference/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="deepseek-开源-dsh-superagent-router-worker-编码代理" tabindex="-1">DeepSeek 开源 dsh-superagent：Router-Worker 编码代理 <a class="header-anchor" href="#deepseek-开源-dsh-superagent-router-worker-编码代理" aria-label="Permalink to &quot;DeepSeek 开源 dsh-superagent：Router-Worker 编码代理&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-01">2026-11-01</time></p><p>DeepSeek 以 MIT 协议开源 dsh-superagent 研究原型，可把 GitHub 与飞书请求转成并行 worker 会话。按其自测模拟，任务完成 p95 从 29.5 分钟降至 15.7 分钟。Router-Worker 结构对多任务并发的收益值得关注。对读者：可基于该原型验证自家工单/PR 流程的并行化改造，注意其仍属研究原型。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/01/deepseek-dsh-superagent-router-worker-coding-agent/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="研究者披露接管-chatgpt-账号的攻击链" tabindex="-1">研究者披露接管 ChatGPT 账号的攻击链 <a class="header-anchor" href="#研究者披露接管-chatgpt-账号的攻击链" aria-label="Permalink to &quot;研究者披露接管 ChatGPT 账号的攻击链&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Simon Willison</span><time datetime="2026-11-01">2026-11-01</time></p><p>Simon Willison 转述 Parameter Labs 发现的漏洞：ChatGPT 的 artifacts/HTML 预览在沙箱 iframe 中运行自定义 HTML 应用，攻击者借 MathLive 等依赖构造出复杂攻击链，可触达 OpenAI API 与私有数据。这提醒「可交互 HTML 预览」类功能的沙箱边界极其关键。对读者：自建同类预览功能时，务必隔离网络与凭证，并审计第三方前端库。</p><p class="news-entry-source"><a href="https://simonwillison.net/2026/Oct/31/how-we-took-over-chatgpt-accounts/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="datasette-llm-0-1a9-发布-自动沿用-llm-默认模型" tabindex="-1">datasette-llm 0.1a9 发布：自动沿用 LLM 默认模型 <a class="header-anchor" href="#datasette-llm-0-1a9-发布-自动沿用-llm-默认模型" aria-label="Permalink to &quot;datasette-llm 0.1a9 发布：自动沿用 LLM 默认模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Simon Willison</span><time datetime="2026-11-01">2026-11-01</time></p><p>datasette-llm 0.1a9 带来一项小但实用的体验改进：插件会自动读取 LLM 的默认模型，因此使用 Datasette Agent 时不再需要显式配置 default_model。作者同时预告 Datasette Agent 将有较大升级。对读者：已用 Datasette 做数据探索的团队可升级简化配置，并为后续 Agent 能力升级预留接入点。</p><p class="news-entry-source"><a href="https://simonwillison.net/2026/Oct/31/datasette-llm/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="用-agent-skills-给团队写一个「前端-review」skill" tabindex="-1">用 Agent Skills 给团队写一个「前端 Review」Skill <a class="header-anchor" href="#用-agent-skills-给团队写一个「前端-review」skill" aria-label="Permalink to &quot;用 Agent Skills 给团队写一个「前端 Review」Skill&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">掘金前端</span><time datetime="2026-11-01">2026-11-01</time></p><p>文章介绍如何借助已捐给 AAIF 的 Agent Skills，用 SKILL.md 把前端 Review 固化为改动范围、类型检查、Lint 与危险禁区四类检查，模板可直接拷进仓库复用。相比堆砌万字 Prompt，这种结构化技能更易维护与协作。对读者：可先把团队最常返工的一类 Review 规则沉淀成 Skill，再逐步扩展覆盖面。</p><p class="news-entry-source"><a href="https://juejin.cn/post/7702637146160201770" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div>',8)])])}const u=a(n,[["render",i]]);export{m as __pageData,u as default};
